css='''@import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700&family=Playfair+Display:wght@400;500;600&display=swap');:root{--bg:#140c1a;--surface:#211428;--gold:#d5a769;--ink:#f8f0e7;--muted:#c7b6c9}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.75 Manrope,Arial,sans-serif}a{color:inherit;text-decoration:none}a:hover{color:var(--gold)}.wrap{max-width:1160px;margin:auto;padding:0 26px}.nav{display:flex;justify-content:space-between;align-items:center;gap:20px;padding-top:20px;padding-bottom:20px}.brand{font:25px 'Playfair Display',serif;letter-spacing:.02em}.navlinks{display:flex;align-items:center;gap:24px;flex-wrap:wrap}.lang{border:1px solid #806b82;padding:5px 12px;border-radius:30px}.btn{display:inline-flex;justify-content:center;align-items:center;padding:13px 25px;background:var(--gold);color:#211224;border-radius:28px;font-weight:700;border:0;cursor:pointer}.btn:hover{background:#f0c78d;color:#211224}.outline{background:transparent;color:var(--gold);border:1px solid var(--gold)}.hero{position:relative;overflow:hidden;background:radial-gradient(circle at 72% 37%,#62364f 0%,#28152f 36%,#140c1a 72%);min-height:640px}.hero-inner{display:grid;grid-template-columns:1.08fr .92fr;align-items:center;gap:40px;padding-top:55px;padding-bottom:75px}.eyebrow{color:var(--gold);font-size:11px;text-transform:uppercase;letter-spacing:.25em;font-weight:700}h1,h2,h3{font-family:'Playfair Display',Georgia,serif;font-weight:400;line-height:1.15}h1{font-size:clamp(48px,6.4vw,88px);margin:24px 0}h2{font-size:clamp(35px,4vw,55px);margin:10px 0 28px}h3{font-size:25px;margin:0 0 12px}p{color:var(--muted)}.lead{font-size:17px;max-width:570px}.portrait-wrap{position:relative;max-width:430px;margin:auto}.portrait-wrap:before{content:'';position:absolute;inset:-22px;border:1px solid #9c755c;border-radius:48% 48% 4px 4px;opacity:.6}.portrait{display:block;width:100%;aspect-ratio:4/5;object-fit:cover;object-position:top;border-radius:47% 47% 3px 3px;filter:saturate(.85)}.section{padding:95px 0}.section.alt{background:#1d1124}.section-intro{max-width:700px;margin-bottom:35px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:17px}.tile{background:linear-gradient(150deg,#39243d,#24152b);border:1px solid #5c3e59;min-height:250px;padding:26px;display:flex;flex-direction:column;justify-content:space-between;transition:transform .2s}.tile:hover{transform:translateY(-4px);border-color:var(--gold)}.tile .num{color:var(--gold);font-size:13px}.tile h3{font-size:24px}.tile .arrow{color:var(--gold);font-size:24px}.about{display:grid;grid-template-columns:.8fr 1.2fr;gap:70px;align-items:center}.about img{width:100%;max-height:560px;object-fit:cover;object-position:top}.certificate{width:145px!important;max-height:200px!important;object-fit:contain!important;margin-top:15px}.cta{background:radial-gradient(circle at 80% 30%,#51304d,#24142b 60%);text-align:center;padding:90px 20px}.cta p{max-width:570px;margin:0 auto 28px}.crumb{padding:28px 0;color:var(--gold);font-size:13px}.detail{max-width:830px;padding-bottom:80px}.detail h1{font-size:clamp(40px,5vw,66px)}.subgrid{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin:38px 0}.sub{border-left:2px solid var(--gold);background:#25182d;padding:18px 23px}.form{display:grid;gap:14px;max-width:580px;margin:30px auto 0;text-align:left}.form input,.form textarea,.form select{width:100%;background:#211428;border:1px solid #6a526d;border-radius:4px;color:white;padding:13px 16px;font:inherit}.form textarea{min-height:100px}.form label{font-size:13px;color:#dfcbd9}.note{font-size:12px}.foot{padding:35px 0;border-top:1px solid #473049;display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap;color:#b9a8ba}.status{color:#eac78f;min-height:25px}.placeholder{border:1px dashed #8d728f;padding:20px;color:#d7c2d7;font-style:italic}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}.hero-inner{gap:25px}.navlinks{gap:10px}}@media(max-width:650px){.nav{align-items:flex-start}.navlinks{font-size:12px}.hero-inner,.about{grid-template-columns:1fr}.hero-inner{padding-top:25px}.portrait-wrap{width:75%;margin-top:25px}.grid,.subgrid{grid-template-columns:1fr}.section{padding:60px 0}.hero{min-height:unset}.tile{min-height:180px}h1{font-size:48px}}'''
