js='''document.querySelectorAll('form[data-booking]').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const status=form.querySelector('.status');status.textContent='Отправляем… / Se trimite…';const data=Object.fromEntries(new FormData(form));try{const r=await fetch('/api/booking',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!r.ok)throw Error();status.textContent='Спасибо! Заявка отправлена. / Mulțumim! Cererea a fost trimisă.';form.reset()}catch{status.textContent='Отправка пока не настроена. / Trimiterea nu este configurată încă.'}}));'''
(p/'assets'/'app.js').write_text(js)
for lang in ['ru','ro']:
 ru=lang=='ru'; t=lambda a,b:a if ru else b
 def link(slug=''):return f'/{lang}/'+(slug+'/' if slug else '')
 def header():return f'''<header class="wrap nav"><a class="brand" href="{link()}">Viorica Cazac</a><nav class="navlinks"><a href="{link()}#directions">{t('Направления','Direcții')}</a><a href="{link()}#about">{t('Обо мне','Despre mine')}</a><a href="{link()}#contact">{t('Контакты','Contact')}</a><a class="lang" href="/{'ro' if ru else 'ru'}/">{'RO' if ru else 'RU'} ↗</a></nav></header>'''
 def footer():return f'''<footer class="wrap foot"><span>© Viorica Cazac · 2026</span><span>{t('Информация на сайте не заменяет медицинскую помощь.','Informațiile nu înlocuiesc asistența medicală.')}</span></footer><script src="/assets/app.js"></script>'''
 def page(body,title):return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#140c1a"><meta name="description" content="Viorica Cazac — {escape(title)}"><title>{escape(title)} — Viorica Cazac</title><link rel="stylesheet" href="/assets/style.css"></head><body>{header()}{body}{footer()}</body></html>'''
 cards=''.join(f'''<a class="tile" href="{link(slug)}"><span class="num">{i:02d} / 08</span><h3>{escape(r if ru else ro)}</h3><span class="arrow">↗</span></a>''' for i,(slug,r,ro,_) in enumerate(services,1))
 form=f'''<form class="form" data-booking><label>{t('Ваше имя','Numele dvs.')}<input name="name" required maxlength="100" autocomplete="name"></label><label>{t('Контакт (Telegram, телефон или email)','Contact (Telegram, telefon sau email)')}<input name="contact" required maxlength="200"></label><label>{t('Интересующее направление','Direcția de interes')}<select name="service"><option value="">{t('Выберите направление','Alegeți o direcție')}</option>{''.join(f'<option value="{escape(slug)}">{escape(r if ru else ro)}</option>' for slug,r,ro,_ in services)}</select></label><label>{t('Комментарий','Mesaj')}<textarea name="message" maxlength="1500"></textarea></label><input type="text" name="website" tabindex="-1" autocomplete="off" style="position:absolute;left:-9999px" aria-hidden="true"><button class="btn" type="submit">{t('Отправить заявку','Trimite cererea')}</button><div class="status" role="status"></div><p class="note">{t('Форма заработает после подключения Telegram-бота.','Formularul va funcționa după conectarea botului Telegram.')}</p></form>'''
 home=f'''<main><section class="hero"><div class="wrap hero-inner"><div><div class="eyebrow">Viorica Cazac · {t('Практики самопознания','Practici de autocunoaștere')}</div><h1>{t('Путь к себе начинается внутри','Drumul spre sine începe în interior')}</h1><p class="lead">{t('Пространство для внимательного знакомства с собой, своими переживаниями и внутренними ресурсами.','Un spațiu pentru a vă cunoaște mai bine, emoțiile și resursele interioare.')}</p><p><a class="btn" href="#contact">{t('Записаться на консультацию','Solicită o consultație')}</a></p></div><div class="portrait-wrap"><img class="portrait" src="/assets/portrait.jpg" alt="Viorica Cazac"></div></div></section><section class="section" id="directions"><div class="wrap"><div class="eyebrow">{t('Направления работы','Direcții de activitate')}</div><h2>{t('Восемь путей к внутренней гармонии','Opt direcții de explorare interioară')}</h2><p class="section-intro">{t('Выберите направление, чтобы узнать, какие практики в него входят. Подробные авторские описания будут добавлены после получения материалов.','Alegeți o direcție. Descrierile complete vor fi adăugate după primirea materialelor.')}</p><div class="grid">{cards}</div></div></section><section class="section alt" id="about"><div class="wrap about"><div><img src="/assets/portrait-white.jpg" alt="Viorica Cazac"></div><div><div class="eyebrow">{t('Знакомство','Cunoaște-mă')}</div><h2>{t('Виорика Казак','Viorica Cazac')}</h2><p>{t('Практик, работающий с темами внутреннего состояния, самопознания и личных изменений.','Practiciană în domeniul autocunoașterii și dezvoltării personale.')}</p><div class="placeholder">{t('Здесь появится рассказ Виорики о себе, опыте и образовании.','Aici va apărea prezentarea Vioricăi, experiența și studiile sale.')}</div><p>{t('Документы об обучении','Documente de formare')}</p><a href="/assets/certificate.jpg" target="_blank" rel="noopener"><img class="certificate" src="/assets/certificate.jpg" alt="Certificate"></a></div></div></section><section class="cta" id="contact"><div class="wrap"><div class="eyebrow">{t('Связаться','Contact')}</div><h2>{t('Начните с разговора','Începeți cu o conversație')}</h2><p>{t('Оставьте заявку, чтобы обсудить подходящее направление и формат встречи.','Lăsați un mesaj pentru a discuta direcția și formatul întâlnirii.')}</p>{form}</div></section></main>'''
 dest=p/lang;dest.mkdir(exist_ok=True);(dest/'index.html').write_text(page(home,t('Главная','Acasă')))
 for slug,r,ro,items in services:
  title=r if ru else ro
  subtitles=''.join(f'<div class="sub">{escape(item if ru else "Descriere în pregătire · "+item)}</div>' for item in items)
  body=f'''<main><div class="wrap crumb"><a href="{link()}">{t('Главная','Acasă')}</a> / <a href="{link()}#directions">{t('Направления','Direcții')}</a></div><section class="wrap detail"><div class="eyebrow">Viorica Cazac · {t('Направление','Direcție')}</div><h1>{escape(title)}</h1><p class="lead">{t('В этом разделе собраны практики данного направления. Подробное описание, формат работы и условия будут добавлены после согласования материалов с Виорикой.','Această pagină prezintă practicile din această direcție. Descrierea detaliată va fi adăugată după aprobarea textelor.')}</p><h2>{t('Практики','Practici')}</h2><div class="subgrid">{subtitles}</div><div class="placeholder">{t('Место для авторского текста, подробностей о сеансах и ответов на вопросы.','Spațiu rezervat pentru textul final, informații despre sesiuni și întrebări frecvente.')}</div><p style="margin-top:40px"><a class="btn" href="{link()}#contact">{t('Оставить заявку','Trimite o cerere')}</a></p></section></main>'''
  d=dest/slug;d.mkdir(exist_ok=True);(d/'index.html').write_text(page(body,title))
(p/'index.html').write_text('<!doctype html><html><head><meta http-equiv="refresh" content="0;url=/ru/"></head><body><a href="/ru/">Русская версия</a></body></html>')
